# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student):
    last = student.last_name.lower()
    return (last, student.first_name.lower())


def _check(students: List[Student], seats: int) -> None:
    if seats <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _layout(ordered, seats) -> List[str]:
    starts = range(0, len(ordered), seats)
    chunks = [ordered[head:head + seats] for head in starts]
    names = [_join_names(chunk) for chunk in chunks]
    return [
        f"Row {rown}: {text}"
        for rown, text in enumerate(names, 1)
    ]


def _join_names(chunk: List[Student]) -> str:
    return " | ".join(item.display_name for item in chunk)


# ---
def seating_rows(
    students: List[Student], seats: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    _check(students, seats)
    return _layout(sorted(students, key=_sort_key), seats)

