# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student("id", last, first, "A")


PEOPLE = [
    make("Halloway", "Juno"),
    make("Dunmere", "Piet"),
    make("Albrecht", "Sol"),
]


class SeatingTests(unittest.TestCase):
    def test_sorted_rows(self):
        rows = seating_rows(PEOPLE, 2)
        self.assertEqual(rows, [
            "Row 1: Albrecht, Sol | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row(self):
        rows = seating_rows(PEOPLE, 10)
        self.assertEqual(len(rows), 1)

    def test_same_last_name_uses_first(self):
        pair = [make("Lowe", "Zed"), make("Lowe", "Amy")]
        rows = seating_rows(pair, 2)
        want = "Row 1: Lowe, Amy | Lowe, Zed"
        self.assertEqual(rows, [want])

    def test_bad_seat_counts(self):
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(PEOPLE, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
